
-- ============================================================
-- HostelHub
-- V20__hostler_lifecycle_billing_pricing_payments.sql
--
-- Pricing rules (per person per month):
-- NORMAL:
--   Sharing 1 = 9000
--   Sharing 2 = 8000
--   Sharing 3 = 7000
--   Sharing 4 = 6500
--   Sharing 5 = 6000
--
-- AC:
--   Sharing 1-5 = 8000
--
-- IMPORTANT:
-- 1. Do not edit previously applied V1-V19 migrations.
-- 2. Verify hostels.id is BIGINT and hostels.status uses ACTIVE.
-- 3. New hostels must receive pricing through PricingService.
-- 4. Requires PostgreSQL btree_gist for overlap enforcement.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Enable support for exclusion constraints
-- ------------------------------------------------------------

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ------------------------------------------------------------
-- 2. Create pricing_rules
-- ------------------------------------------------------------

CREATE TABLE pricing_rules (
                               id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

                               hostel_id BIGINT NOT NULL,

                               room_type VARCHAR(20) NOT NULL,
                               sharing_capacity SMALLINT NOT NULL,

                               billing_basis VARCHAR(20) NOT NULL DEFAULT 'MONTHLY',

                               rate_per_person NUMERIC(12, 2) NOT NULL,

                               effective_from DATE NOT NULL,
                               effective_to DATE,

                               active BOOLEAN NOT NULL DEFAULT TRUE,

                               created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
                               updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

                               CONSTRAINT fk_pricing_rules_hostel
                                   FOREIGN KEY (hostel_id)
                                       REFERENCES hostels (id)
                                       ON DELETE RESTRICT,

                               CONSTRAINT chk_pricing_rules_room_type
                                   CHECK (room_type IN ('NORMAL', 'AC')),

                               CONSTRAINT chk_pricing_rules_sharing
                                   CHECK (sharing_capacity BETWEEN 1 AND 5),

                               CONSTRAINT chk_pricing_rules_billing_basis
                                   CHECK (billing_basis = 'MONTHLY'),

                               CONSTRAINT chk_pricing_rules_rate
                                   CHECK (rate_per_person >= 0),

                               CONSTRAINT chk_pricing_rules_effective_dates
                                   CHECK (
                                       effective_to IS NULL
                                           OR effective_to >= effective_from
                                       ),

                               CONSTRAINT uq_pricing_rules_version
                                   UNIQUE (
                                           hostel_id,
                                           room_type,
                                           sharing_capacity,
                                           billing_basis,
                                           effective_from
                                       ),

    -- Prevent overlapping active date ranges for the same
    -- hostel, room type, sharing capacity and billing basis.
                               CONSTRAINT ex_pricing_rules_no_active_overlap
                                   EXCLUDE USING GIST (
            hostel_id WITH =,
            room_type WITH =,
            sharing_capacity WITH =,
            billing_basis WITH =,
            daterange(
                effective_from,
                CASE
                    WHEN effective_to IS NULL THEN NULL
                    ELSE effective_to + 1
                END,
                '[)'
            ) WITH &&
        )
        WHERE (active = TRUE)
);

-- ------------------------------------------------------------
-- 3. Indexes
-- ------------------------------------------------------------

CREATE INDEX idx_pricing_rules_hostel_active
    ON pricing_rules (hostel_id, active);

CREATE INDEX idx_pricing_rules_lookup
    ON pricing_rules (
                      hostel_id,
                      room_type,
                      sharing_capacity,
                      billing_basis,
                      effective_from DESC
        );

-- ------------------------------------------------------------
-- 4. Seed prices for existing active hostels
-- ------------------------------------------------------------

INSERT INTO pricing_rules (
    hostel_id,
    room_type,
    sharing_capacity,
    billing_basis,
    rate_per_person,
    effective_from,
    active
)
SELECT
    h.id,
    p.room_type,
    p.sharing_capacity,
    'MONTHLY',
    p.rate_per_person,
    CURRENT_DATE,
    TRUE
FROM hostels h
         CROSS JOIN (
    VALUES
        ('NORMAL', 1, 9000.00::NUMERIC),
        ('NORMAL', 2, 8000.00::NUMERIC),
        ('NORMAL', 3, 7000.00::NUMERIC),
        ('NORMAL', 4, 6500.00::NUMERIC),
        ('NORMAL', 5, 6000.00::NUMERIC),
        ('AC',     1, 8000.00::NUMERIC),
        ('AC',     2, 8000.00::NUMERIC),
        ('AC',     3, 8000.00::NUMERIC),
        ('AC',     4, 8000.00::NUMERIC),
        ('AC',     5, 8000.00::NUMERIC)
) AS p(room_type, sharing_capacity, rate_per_person)
WHERE h.status = 'ACTIVE'
    ON CONFLICT (
    hostel_id,
    room_type,
    sharing_capacity,
    billing_basis,
    effective_from
)
DO NOTHING;
